import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { ListClasses } from "../list.styles";

type ListFilterChipBarProps = {
  children: React.ReactNode;
  className?: string;
};

export const ListFilterChipBar = forwardRef<HTMLDivElement, ListFilterChipBarProps>(
  ({ children, className, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(ListClasses.filterChipBars, className)} {...props}>
        {children}
      </div>
    );
  },
);

ListFilterChipBar.displayName = "List.FilterChipBars";
